"""
Flask 应用工厂
框架代码，不包含具体业务逻辑
"""
import os
from flask import Flask, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from configuration import get_config

db = SQLAlchemy()

# 项目根目录
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

def create_app(config_name=None):
    """应用工厂函数"""
    # 设置模板路径
    template_dir = os.path.join(BASE_DIR, 'templates')
    app = Flask(__name__, template_folder=template_dir)

    # 加载配置
    if config_name:
        app.config.from_object(config_name)
    else:
        app.config.from_object(get_config())

    # 初始化扩展
    db.init_app(app)

    # CORS 支持
    CORS(app)

    # ==== 在这里注册业务蓝图 ====
    from app.routes.blog_routes import blog_routes
    app.register_blueprint(blog_routes, url_prefix='/api')
    # ==============================

    # 首页路由
    @app.route('/')
    def index():
        return render_template('index.html')

    # 健康检查
    @app.route('/health')
    def health():
        return {'status': 'ok'}

    # 博客列表页
    @app.route('/blog')
    def blog_list():
        return render_template('blog_list.html')

    # 博客详情页
    @app.route('/blog/<int:id>')
    def blog_detail(id):
        return render_template('blog_detail.html', blog={})

    # 创建数据库表
    with app.app_context():
        db.create_all()

    # 新建博客页面
    @app.route('/blog/new')
    def blog_new():
        return render_template('blog_new.html')

    # 404 错误页面
    @app.errorhandler(404)
    def page_not_found(e):
        return render_template('404.html'), 404

    return app

from flask import Blueprint, request, jsonify
from app.models.blog import Blog
from app import db
from app.utils.image_upload import save_image

blog_routes = Blueprint('blog_routes', __name__)

@blog_routes.route('/blogs', methods=['GET'])
def get_blogs():
    blogs = Blog.query.all()
    return jsonify([blog.to_dict() for blog in blogs])

@blog_routes.route('/blogs/<int:id>', methods=['GET'])
def get_blog(id):
    blog = Blog.query.get(id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404
    return jsonify(blog.to_dict())

@blog_routes.route('/blogs', methods=['POST'])
def create_blog():
    data = request.form
    title = data.get('title')
    description = data.get('description')
    image = request.files.get('image')

    if not title or not description:
        return jsonify({'error': 'Title and description are required'}), 400

    image_url = save_image(image) if image else None

    blog = Blog(title=title, description=description, image_url=image_url)
    db.session.add(blog)
    db.session.commit()

    return jsonify(blog.to_dict()), 201

@blog_routes.route('/blogs/<int:id>', methods=['PUT'])
def update_blog(id):
    blog = Blog.query.get(id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404

    data = request.form
    blog.title = data.get('title', blog.title)
    blog.description = data.get('description', blog.description)
    image = request.files.get('image')

    if image:
        blog.image_url = save_image(image)

    db.session.commit()
    return jsonify(blog.to_dict())

@blog_routes.route('/blogs/<int:id>', methods=['DELETE'])
def delete_blog(id):
    blog = Blog.query.get(id)
    if not blog:
        return jsonify({'error': 'Blog not found'}), 404

    db.session.delete(blog)
    db.session.commit()
    return jsonify({'message': 'Blog deleted successfully'})
